?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tabel Gabungan | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Ringkasan Terintegrasi</p><h1>Tabel Gabungan</h1></div></div><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nomor Permohonan</th><th>Perusahaan</th><th>IPPKH</th><th>Jenis</th><th>Status</th><th>Lokasi</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT nomor_permohonan,nama_pemohon,nomor_ippkh,jenis_permohonan,status,provinsi,kabupaten FROM permohonan ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_permohonan'])?></td><td><?=htmlspecialchars($r['nama_pemohon'])?></td><td><?=htmlspecialchars($r['nomor_ippkh'])?></td><td><?=htmlspecialchars($r['jenis_permohonan'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars(trim($r['kabupaten'].' '.$r['provinsi']))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada data gabungan.</td></tr><?php endif?></tbody></table></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
